use std::io::{self, Read};
fn mn(a: i32, b: i32) -> i32 {
    a.min(b)
}
fn mx(a: i32, b: i32) -> i32 {
    a.max(b)
}
fn emit(x: i32) {
    print!("{} ", x);
}
fn emitstr(a: &Vec<i32>, n: i32) {
    if n == 0 {
        print!("-");
    }
    for i in 0..n {
        print!("{}", a[i as usize] as u8 as char);
    }
    print!(" ");
}
struct Reader {
    t: Vec<String>,
    p: usize,
}
impl Reader {
    fn new() -> Self {
        let mut s = String::new();
        io::stdin().read_to_string(&mut s).unwrap();
        Self {
            t: s.split_whitespace().map(String::from).collect(),
            p: 0,
        }
    }
    fn read(&mut self) -> i32 {
        let x = self.t[self.p].parse().unwrap();
        self.p += 1;
        x
    }
    fn readstr(&mut self, a: &mut Vec<i32>) -> i32 {
        let s = &self.t[self.p];
        self.p += 1;
        if s == "-" {
            return 0;
        }
        for (i, c) in s.bytes().enumerate() {
            a[i] = c as i32;
        }
        s.len() as i32
    }
}
fn main() {
    let mut reader = Reader::new();
    let mut a = vec![0i32; 20000];
    let mut b = vec![0i32; 20000];
    let mut d = vec![0i32; 20000];
    let mut e = vec![0i32; 20000];
    let mut bottom: i32 = 0;
    let mut cols: i32 = 0;
    let mut i: i32 = 0;
    let mut j: i32 = 0;
    let mut left: i32 = 0;
    let mut right: i32 = 0;
    let mut rows: i32 = 0;
    let mut top: i32 = 0;
    rows = reader.read();
    cols = reader.read();
    i = 0;
    while i < (rows * cols) {
        a[(i) as usize] = reader.read();
        i += 1;
    }
    top = 0;
    bottom = (rows - 1);
    left = 0;
    right = (cols - 1);
    while ((top <= bottom) && (left <= right)) {
        j = left;
        while j < (right + 1) {
            emit(a[((top * cols) + j) as usize]);
            j += 1;
        }
        top = (top + 1);
        i = top;
        while i < (bottom + 1) {
            emit(a[((i * cols) + right) as usize]);
            i += 1;
        }
        right = (right - 1);
        if (top <= bottom) {
            j = right;
            while j > (left - 1) {
                emit(a[((bottom * cols) + j) as usize]);
                j += -1;
            }
            bottom = (bottom - 1);
        }
        if (left <= right) {
            i = bottom;
            while i > (top - 1) {
                emit(a[((i * cols) + left) as usize]);
                i += -1;
            }
            left = (left + 1);
        }
    }
}
